// Package tsuraraplugin writes tsurara plugins in Go. A plugin is a main package that
// calls Run with its stages; tsurara runs it once per run (runtime [go, run] with the package
// directory as the module) and calls the stages it declares over the session protocol (design.md
// 11.2). The types of the model, the manifest and the inputs are in the package protocol, generated by
// tsurara from spec/plugin-protocol.schema.json.
package tsuraraplugin

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/tsurara-openapi/tsurara/packages/plugin-go/protocol"
)

// SessionProtocol is the session protocol this SDK speaks.
const SessionProtocol = 1

// Plugin is a name and any of the stages. TransformDocument and TransformModel work on JSON values,
// so that nothing a newer tsurara adds is lost.
type Plugin struct {
	Name              string
	TransformDocument func(document json.RawMessage) (json.RawMessage, error)
	TransformModel    func(model json.RawMessage) (json.RawMessage, error)
	Extend            func(input protocol.ExtendInput) ([]protocol.OutputFile, error)
	TransformFiles    func(files []protocol.OutputFile) ([]protocol.OutputFile, error)
}

type request struct {
	Type  string          `json:"type"`
	Stage string          `json:"stage"`
	Input json.RawMessage `json:"input"`
}

// Run serves the plugin on stdin and stdout until stdin closes.
func Run(p Plugin) {
	if err := Serve(p, os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// Serve serves the plugin on r and w until r ends.
func Serve(p Plugin, r io.Reader, w io.Writer) error {
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 1024*1024), 1<<30)
	enc := json.NewEncoder(w)
	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var req request
		if err := json.Unmarshal(line, &req); err != nil {
			return err
		}
		if req.Type == "hello" {
			if err := enc.Encode(map[string]any{
				"type":     "hello",
				"protocol": SessionProtocol,
				"name":     p.Name,
				"stages":   stages(p),
			}); err != nil {
				return err
			}
			continue
		}
		output, err := call(p, req.Stage, req.Input)
		var answer map[string]any
		if err != nil {
			answer = map[string]any{"type": "error", "message": err.Error()}
		} else {
			answer = map[string]any{"type": "result", "output": output}
		}
		if err := enc.Encode(answer); err != nil {
			return err
		}
	}
	return scanner.Err()
}

func stages(p Plugin) []string {
	var out []string
	if p.TransformDocument != nil {
		out = append(out, "transformDocument")
	}
	if p.TransformModel != nil {
		out = append(out, "transformModel")
	}
	if p.Extend != nil {
		out = append(out, "extend")
	}
	if p.TransformFiles != nil {
		out = append(out, "transformFiles")
	}
	return out
}

func call(p Plugin, stage string, input json.RawMessage) (any, error) {
	switch {
	case stage == "transformDocument" && p.TransformDocument != nil:
		return p.TransformDocument(input)
	case stage == "transformModel" && p.TransformModel != nil:
		return p.TransformModel(input)
	case stage == "extend" && p.Extend != nil:
		var in protocol.ExtendInput
		if err := json.Unmarshal(input, &in); err != nil {
			return nil, err
		}
		return p.Extend(in)
	case stage == "transformFiles" && p.TransformFiles != nil:
		var files []protocol.OutputFile
		if err := json.Unmarshal(input, &files); err != nil {
			return nil, err
		}
		return p.TransformFiles(files)
	}
	return nil, fmt.Errorf("the plugin has no %s stage", stage)
}
